import React from 'react';
import MuiTooltip from '@material-ui/core/Tooltip';

// The look (white rounded card, soft border and shadow, arrow) comes from the theme's MuiTooltip override in theme/index.js, the same
// one the sidebar notes use. It used to force a black box here, which left the theme's dark text unreadable on it.
function BootstrapTooltip(props) {
  return <MuiTooltip arrow {...props} placement={props?.placement} />;
}

export default function CommonTooltip(props) {
  const { placement = 'top', content = '', style = {}, className = '' } = props;
  return (
    <BootstrapTooltip style={style} className={className} placement={placement} title={content}>
      <b>{!content ? <span>{props.children}</span> : props.children}</b>
    </BootstrapTooltip>
  );
}
