// What a page loaded last time, kept for as long as the app stays open, so coming back to the page (or switching between the tabs of a
// page) shows it at once and the fresh copy is read quietly behind it ("soft" refresh) instead of a skeleton every time.
// Keys name the school and batch the data is for, e.g. `subjects:1:7`.
const store = new Map();

export const cacheGet = key => store.get(key);

export const cacheSet = (key, value) => {
  store.set(key, value);
  return value;
};

export const cacheClear = () => store.clear();
