import axios from 'axios';

// Reads that were asked a moment ago are not asked again. The same GET (same address, same login) that is already on its way, or that
// finished less than TTL_MS ago, gets that answer instead of a new request - so switching between tabs or pages that read the same
// list does not read it again and again. Any write (POST / PUT / PATCH / DELETE) clears everything, so a list read right after a change
// is always fresh. Files (anything that is not plain JSON) are never kept.
export const TTL_MS = 2000;

const copy = data => (data !== null && typeof data === 'object' ? JSON.parse(JSON.stringify(data)) : data);
// every caller gets its own copy, so one page sorting or editing the list in place cannot change what another page reads
const answer = response => ({ ...response, data: copy(response.data) });

export const makeCachedAdapter = (baseAdapter, now = () => Date.now()) => {
  const store = new Map(); // key -> { at, promise }
  const adapter = config => {
    const method = String(config.method || 'get').toLowerCase();
    if (method !== 'get') {
      store.clear();
      return baseAdapter(config).finally(() => store.clear());
    }
    if (config.responseType && config.responseType !== 'json') return baseAdapter(config);
    const auth = config.headers?.get ? config.headers.get('Authorization') : config.headers?.Authorization;
    const key = `${config.baseURL || ''}${config.url}|${JSON.stringify(config.params || {})}|${auth || ''}`;
    const hit = store.get(key);
    if (hit && now() - hit.at < TTL_MS) return hit.promise.then(answer);
    const promise = baseAdapter(config);
    const entry = { at: now(), promise };
    store.set(key, entry);
    // a failed read is not kept; a finished one stays for TTL_MS from the moment it finished
    promise.then(
      () => {
        entry.at = now();
      },
      () => {
        if (store.get(key) === entry) store.delete(key);
      }
    );
    return promise.then(answer);
  };
  adapter.clear = () => store.clear();
  return adapter;
};

export const installGetCache = () => {
  const base = axios.getAdapter ? axios.getAdapter(axios.defaults.adapter) : axios.defaults.adapter;
  axios.defaults.adapter = makeCachedAdapter(base);
};
