// When the server cannot be reached, the dashboard sends the person to a static "under maintenance" page instead of leaving a login
// form or a page that never loads. Only calls to our own API count, and only these failures:
//  - the server (or the proxy in front of it) answered 502, 503 or 504, or
//  - the call got no answer at all AND a second look at the server finds nothing there either (so one dropped call, or a CORS fault on
//    a single route, does not close the whole app).
export const MAINTENANCE_PAGE = '/maintenance.html';
export const DOWN_STATUSES = [502, 503, 504];

export const isApiCall = (error, apiBase) => !!apiBase && String(error?.config?.url || '').startsWith(apiBase);

// 'down' (the server said so), 'silent' (no answer, check again), or '' (an ordinary failure)
export const failureKind = error => {
  const status = error?.response?.status;
  if (status) {
    return DOWN_STATUSES.includes(status) ? 'down' : '';
  }
  if (error?.code === 'ERR_CANCELED') {
    return '';
  }
  const message = String(error?.message || '');
  return error?.code === 'ERR_NETWORK' || error?.code === 'ECONNABORTED' || /network error|timeout/i.test(message)
    ? 'silent'
    : '';
};

// Does anything answer at the server's address? Any HTTP answer counts (even an error page); only "no answer" is false.
export const serverAnswers = async (apiBase, fetchFn = fetch, timeoutMs = 6000) => {
  const controller = typeof AbortController === 'undefined' ? null : new AbortController();
  const timer = controller ? setTimeout(() => controller.abort(), timeoutMs) : null;
  try {
    await fetchFn(apiBase, { mode: 'no-cors', cache: 'no-store', signal: controller?.signal });
    return true;
  } catch (err) {
    return false;
  } finally {
    if (timer) clearTimeout(timer);
  }
};

// The page to go back to from the maintenance page: a path of this site only.
export const maintenanceUrl = (pathWithQuery = '') => {
  const safe = pathWithQuery.startsWith('/') && !pathWithQuery.startsWith('//') ? pathWithQuery : '';
  return safe && safe !== MAINTENANCE_PAGE ? `${MAINTENANCE_PAGE}?from=${encodeURIComponent(safe)}` : MAINTENANCE_PAGE;
};
