import { useCallback, useRef, useState } from 'react';
import { cacheGet, cacheSet } from './softCache';

// useState that is also remembered, while the app stays open, under a key (name the school/batch in it, e.g. `items:7`). A page or tab
// that is opened again starts from what it showed last time, so it can read the fresh copy quietly behind it instead of showing a
// skeleton again. A falsy key does not remember.
export const useCachedState = (key, initial) => {
  const [value, setValue] = useState(() => {
    const hit = key ? cacheGet(key) : undefined;
    return hit !== undefined ? hit : initial;
  });
  const keyRef = useRef(key);
  keyRef.current = key;
  const set = useCallback(next => {
    setValue(prev => {
      const resolved = typeof next === 'function' ? next(prev) : next;
      if (keyRef.current) cacheSet(keyRef.current, resolved);
      return resolved;
    });
  }, []);
  return [value, set];
};

// Was something remembered under this key (even an empty list)?
export const hasCached = key => !!key && cacheGet(key) !== undefined;
