export const login = credentials => async dispatch => {
  const res = await axios.post(`${constants.API_BASE_URL}/api/auth/signin`, credentials);
  // Guardians (parents) use the mobile app, not this web dashboard - SA is kept allowed
  // since it's used here for multi-school switching/management.
  const webAllowedRoles = [constants.roles.admin, constants.roles.teacher, constants.roles.SA];
  if (!webAllowedRoles.includes(res.data?.userRole)) {
    throw { response: { data: { message: MSG.login_role_not_allowed } } };
  }
  setLoggedUserUtils({ ...res.data });
  dispatch(userLoggedIn(res.data));
  // const prismic = await PrismicClient.query('', { pageSize: 100 });
  // console.error({prismic});
  return res.data;
};

export const logout = () => dispatch => {
  dispatch(userLoggedOut());
  localStorage.clear();
};

export const SUSPICIOUS_LOGIN_MESSAGE =
  'We found suspicious activity: your login details do not match our records, so we logged you out. Please login again.';

// The role, user and school kept in the browser can be edited by anyone. When the app opens they are checked against the server:
//  - GET /api/auth/me answers from the signed token; if the stored role, user or school differ from it, the details were changed outside
//    the app, so the session is ended with a message and the person has to login again.
//  - A server without that endpoint (an older one) cannot say, so a person who claims to be the super admin is asked for something only
//    the super admin may read; "Access denied" there ends the session the same way.
// A check that cannot be made at all (offline, a server error) changes nothing; a bad token ends the session as usual (see index.js).
export const verifyStoredLogin = user => async dispatch => {
  if (!user?.accessToken) return;
  const endSuspiciousSession = () => {
    dispatch(showToast(SUSPICIOUS_LOGIN_MESSAGE, 'error'));
    dispatch(logout());
  };
  const isDenied = err => /access denied|not authorized/i.test(JSON.stringify(err?.response?.data || ''));
  try {
    const res = await axios.get(`${constants.API_BASE_URL}/api/auth/me`, constants.setHeader(user.accessToken));
    const server = res.data || {};
    // the school's plan can change after the person signed in: keep the stored copy and the screen in step with the server
    if (server.subscriptionPlan && server.subscriptionPlan !== user.subscriptionPlan) {
      setLoggedUserUtils({ ...user, subscriptionPlan: server.subscriptionPlan });
      dispatch({ type: SET_SUBSCRIPTION_PLAN, plan: server.subscriptionPlan });
    }
    const wrong = ['userRole', 'referenceId', 'schoolId'].some(
      field => server[field] != null && server[field] !== user[field]
    );
    if (wrong) endSuspiciousSession();
  } catch (err) {
    if (err?.response?.status === 401 || user.userRole !== constants.roles.SA) return;
    try {
      await axios.get(
        `${constants.API_BASE_URL}/api/admin/get-all-school-admin/${user.schoolId || 1}?page=1&size=1`,
        constants.setHeader(user.accessToken)
      );
    } catch (probeErr) {
      if (isDenied(probeErr)) endSuspiciousSession();
    }
  }
};

