import React, { useState } from 'react';

// The chosen report of a Reports tab, kept in the browser so a reload (or coming back later) lands on the same one. Only a key that is
// still offered counts; storage that is blocked just means it starts from the default every time.
export const usePersistedReport = (storageKey, items, fallback) => {
  const [value, setValue] = useState(() => {
    try {
      const saved = localStorage.getItem(storageKey);
      return items.some(item => item.key === saved) ? saved : fallback;
    } catch (err) {
      return fallback;
    }
  });
  const change = key => {
    setValue(key);
    try {
      localStorage.setItem(storageKey, key);
    } catch (err) {
      // not saved: the choice still works for this visit
    }
  };
  return [value, change];
};

// "Which report?" as one pill row (icon + name), the same on every Reports tab; what the chosen report shows is one line under
// the row. items are { key, label, icon, description }. Replaces the row of big radio cards.
const ReportPicker = ({ items, value, onChange }) => {
  const current = items.find(item => item.key === value);
  return (
    <div>
      <div className="rui-segments" role="radiogroup">
        {items.map(item => (
          <button
            key={item.key}
            type="button"
            role="radio"
            aria-checked={value === item.key}
            className={value === item.key ? 'on' : ''}
            onClick={() => onChange(item.key)}>
            <i className={item.icon} aria-hidden="true" />
            {item.label}
          </button>
        ))}
      </div>
      <div className="rui-segments-hint">{current?.description}</div>
    </div>
  );
};

export default ReportPicker;
